
// The engine carries its own bare three specifier, which the import map above
// resolves; declaring a second one here would collide on the binding.
// GENERATED by scripts/generate-globe-land-data.mjs — do not edit by hand.
//
// Natural Earth 1:50m land polygons (public domain), simplified to 14910 points
// across 906 rings and packed as zigzag-varint deltas at 1/16° so the
// tool and every HTML export it produces work with no network access at all.
// Provenance and terms: src/lib/tools/THIRD_PARTY_NOTICES.md.

const LAND_QUANT = 16;
const LAND_RING_COUNT = 906;
const LAND_POINT_COUNT = 14910;
const LAND_PACKED =
  '';

// Returns one Float32Array per ring, interleaved [lng, lat, lng, lat, ...] in
// degrees. Decoding is ~1 ms and the result is cached, because the dot mask and
// the coastline outlines both want the same rings.
let cache = null;
function decodeLandRings() {
  if (cache) return cache;

  const raw = typeof atob === 'function'
    ? atob(LAND_PACKED)
    : Buffer.from(LAND_PACKED, 'base64').toString('binary');
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);

  let cursor = 0;
  const next = () => {
    let result = 0;
    let shift = 0;
    for (;;) {
      const byte = bytes[cursor];
      cursor += 1;
      result |= (byte & 0x7f) << shift;
      if ((byte & 0x80) === 0) break;
      shift += 7;
    }
    return (result >>> 1) ^ -(result & 1);
  };

  const ringCount = next();
  const rings = new Array(ringCount);
  for (let r = 0; r < ringCount; r += 1) {
    const count = next();
    const ring = new Float32Array(count * 2);
    let x = 0;
    let y = 0;
    for (let i = 0; i < count; i += 1) {
      x += next();
      y += next();
      ring[i * 2] = x / LAND_QUANT;
      ring[i * 2 + 1] = y / LAND_QUANT;
    }
    rings[r] = ring;
  }

  cache = rings;
  return rings;
}

/**
 * An Earth drawn as a field of dots, spun by drag and by itself.
 *
 * The land geometry is baked, not fetched: `globeLand.data.js` carries Natural
 * Earth's 1:50m coastlines packed into ~42 KB of base64, so a card, the editor
 * and the HTML a buyer downloads all work with no network and no third-party
 * host on the critical path.
 *
 * Two decisions differ from the usual way this effect is built, both for the
 * same reason — a catalogue page mounts more than one of these:
 *
 *   1. Coastlines, the graticule and the ocean live in ONE canvas texture drawn
 *      in equirectangular space and wrapped onto a single sphere. The obvious
 *      alternative — a TubeGeometry per ring — is about 1 000 meshes and 1 000
 *      draw calls before a single dot exists. Stroke width also stays honest in
 *      texture space, where WebGL's `linewidth` is ignored on every desktop
 *      driver. The cost is that outlines are texels rather than geometry, so the
 *      texture is sized against the stage (4096 wide once the stage is large).
 *
 *   2. Every dot is one instance of one 6-gon in a single `InstancedMesh`, so
 *      the whole field is one draw call whether it holds 2 000 dots or 40 000.
 *
 * Equirectangular is a linear mapping — `u = (lng + 180) / 360`,
 * `v = (90 - lat) / 180` — which is why there is no projection library here: the
 * mask, the texture and `SphereGeometry`'s own UVs already agree by construction.
 *
 * Returns its own teardown; the caller disposes geometries, materials, textures
 * and the WebGL context through it.
 */
import * as THREE from '/assets/vendor/three.module.min.js';

// Whether WebGL here is a software rasteriser (SwiftShader in headless Chromium,
// llvmpipe under Mesa). Probed once per document on a throwaway context: the
// answer decides context-creation attributes, so it has to be known before the
// renderer exists. On a software rasteriser the globe drops what only a GPU can
// afford -- MSAA, a 4096-texel surface and mask, anisotropic sampling, a
// device-pixel-ratio above one -- and still reads as the same globe, at a frame
// cost a CPU can carry. Measured on the CI runner (8 vCPU, no GPU, 2026-09-08):
// the full-fat defaults render at ~2 fps with 500 ms frames.
let softwareGL = null;
function isSoftwareGL() {
  if (softwareGL !== null) return softwareGL;
  softwareGL = false;
  try {
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
    if (gl) {
      const info = gl.getExtension('WEBGL_debug_renderer_info');
      const name = String(info ? gl.getParameter(info.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
      softwareGL = /swiftshader|llvmpipe|softpipe|software/i.test(name);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    }
  } catch {
    softwareGL = false;
  }
  return softwareGL;
}

const DEG = Math.PI / 180;
const TAU = Math.PI * 2;

// Radii are relative to a unit sphere. Dots sit exactly ON the ocean rather than
// floating above it. The clearance this used to carry was there so a flat disc
// would not z-fight with the tangent surface underneath it; a sphere intersects
// that surface instead of lying in it, so the clearance buys nothing — and it
// costs: a dot lifted above the ocean projects outside the ocean's silhouette at
// the limb, so the dots on the FAR side of the globe poke out around the edge.
// At 0.007 that was a three-pixel crescent of Pacific dots hanging off the rim
// at a 900 px stage. Flush, a back-facing dot clears the silhouette by its own
// sub-pixel radius and is invisible, which is what the reference does too.
// Markers keep their lift: they are meant to read as pinned above the surface.
const OCEAN_RADIUS = 0.996999;
const DOT_RADIUS = OCEAN_RADIUS;
const MARKER_RADIUS = 1.00999;

function toVector(lat, lng, radius, target) {
  const phi = (90 - lat) * DEG;
  const theta = ((lng + 180) / 360) * TAU;
  const sinPhi = Math.sin(phi);
  return target.set(
    -radius * Math.cos(theta) * sinPhi,
    radius * Math.cos(phi),
    radius * Math.sin(theta) * sinPhi
  );
}

// Parses the marker control: "lat,lng" pairs separated by newlines or
// semicolons, with anything unparseable dropped rather than thrown, because the
// field is edited a keystroke at a time.
function parseMarkers(text) {
  if (typeof text !== 'string') return [];
  return text
    .split(/[;\n]+/)
    .map((entry) => entry.split(',').map((part) => Number.parseFloat(part.trim())))
    .filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng) && Math.abs(lat) <= 90)
    .map(([lat, lng]) => ({ lat, lng: ((((lng + 180) % 360) + 360) % 360) - 180 }))
    .slice(0, 64);
}

// Longitudes are unwrapped into one continuous strip before anything is drawn.
// A step wider than half the world is a ring crossing the antimeridian, so 360
// is added or subtracted to keep the path going instead of teleporting back
// across the canvas and dragging a stripe with it.
//
// A ring that ends a whole world away from where it started has encircled a
// pole — that is Antarctica, and only Antarctica in this dataset. Such a ring
// has to be closed along the pole edge: the straight line canvas would close it
// with instead cuts a wedge diagonally across the southern ocean.
function unwrapRings(rings) {
  return rings.map((ring) => {
    const points = new Float64Array(ring.length);
    let offset = 0;
    let previous = ring[0];
    let latSum = 0;
    points[0] = ring[0];
    points[1] = ring[1];
    for (let i = 2; i < ring.length; i += 2) {
      const lng = ring[i];
      const step = lng - previous;
      if (step > 180) offset -= 360;
      else if (step < -180) offset += 360;
      previous = lng;
      points[i] = lng + offset;
      points[i + 1] = ring[i + 1];
      latSum += ring[i + 1];
    }
    const wrapped = Math.abs(points[points.length - 2] - points[0]) > 180;
    return { points, wrapped, poleLat: latSum < 0 ? -90 : 90 };
  });
}

// One ring per subpath, in equirectangular pixel space, offset by whole worlds
// so a shape clipped at the seam is completed by the copy that owns its other
// half. `closeAtPole` is the difference between a fill and a stroke: the fill
// needs the pole segments, the outline must not draw them.
function traceRings(ctx, unwrapped, width, height, offsetX, closeAtPole) {
  const sx = width / 360;
  const sy = height / 180;
  for (const ring of unwrapped) {
    const points = ring.points;
    ctx.moveTo((points[0] + 180) * sx + offsetX, (90 - points[1]) * sy);
    for (let i = 2; i < points.length; i += 2) {
      ctx.lineTo((points[i] + 180) * sx + offsetX, (90 - points[i + 1]) * sy);
    }
    if (closeAtPole && ring.wrapped) {
      const y = (90 - ring.poleLat) * sy;
      ctx.lineTo((points[points.length - 2] + 180) * sx + offsetX, y);
      ctx.lineTo((points[0] + 180) * sx + offsetX, y);
    }
  }
}

function drawLandPath(ctx, unwrapped, width, height) {
  ctx.beginPath();
  for (const offset of [-width, 0, width]) {
    traceRings(ctx, unwrapped, width, height, offset, true);
  }
}

// A boolean land mask sampled per dot. Canvas fill uses the non-zero winding
// rule, which is what the Natural Earth ring orientation expects: holes (the
// Caspian, Africa's great lakes) come back as ocean without extra work.
function buildLandMask(rings, width, height) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = '#fff';
  drawLandPath(ctx, rings, width, height);
  ctx.fill();

  const pixels = ctx.getImageData(0, 0, width, height).data;
  const mask = new Uint8Array(width * height);
  for (let i = 0; i < mask.length; i += 1) mask[i] = pixels[i * 4] > 127 ? 1 : 0;
  return { mask, width, height };
}

function sampleMask(land, lat, lng) {
  const x = Math.min(land.width - 1, Math.max(0, Math.floor(((lng + 180) / 360) * land.width)));
  const y = Math.min(land.height - 1, Math.max(0, Math.floor(((90 - lat) / 180) * land.height)));
  return land.mask[y * land.width + x] === 1;
}

// Rows every `spacing` degrees of latitude, and within a row enough dots to keep
// the arc between them the same as the arc between rows. A naive lat/lng lattice
// stacks its columns into a knot at the poles; this keeps the field even.
function dotPositions(land, spacingDeg, landOnly) {
  const spacing = Math.max(0.349999, spacingDeg);
  const rows = Math.max(3, Math.round(180 / spacing));
  const out = [];
  for (let r = 0; r < rows; r += 1) {
    const lat = -90 + ((r + 0.499999) * 180) / rows;
    const columns = Math.max(1, Math.round((360 * Math.cos(lat * DEG)) / spacing));
    for (let c = 0; c < columns; c += 1) {
      const lng = -180 + ((c + 0.499999) * 360) / columns;
      if (landOnly && !sampleMask(land, lat, lng)) continue;
      out.push(lat, lng);
    }
  }
  return out;
}

// A colour the canvas should not paint at all. `transparent` is what the Stage
// background already uses for the same idea, and a zero-alpha hex is what a
// colour picker hands back when it is dragged to nothing.
function isClear(color) {
  if (!color) return true;
  const value = String(color).trim().toLowerCase();
  return value === 'transparent' || value === 'none' || /^#[0-9a-f]{6}00$/.test(value);
}

// Ocean, optional land fill, coastlines and graticule, all in one texture. The
// graticule is drawn first so a coastline crosses over it, which is the reading
// order the eye expects.
function paintSurface(canvas, rings, config) {
  const { width, height } = canvas;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, width, height);
  // A transparent ocean is a setting, not a missing one. Stamped onto a dark
  // page a black sphere reads as a disc cut out of the surface behind it; left
  // clear, the page shows through and only the land, the coastline and whatever
  // grid is on survive. Nothing about the geometry changes: the sphere still
  // writes depth over its whole silhouette, and that — not the fill — is what
  // hides the dots on the far side.
  if (!isClear(config.oceanColor)) {
    ctx.fillStyle = config.oceanColor;
    ctx.fillRect(0, 0, width, height);
  }

  const texelsPerDegree = width / 360;

  if (config.fill === 'solid') {
    ctx.fillStyle = config.landColor;
    drawLandPath(ctx, rings, width, height);
    ctx.fill();
  }

  if (config.showGraticule && config.graticuleStep > 0) {
    ctx.strokeStyle = config.graticuleColor;
    ctx.globalAlpha = config.graticuleOpacity;
    ctx.lineWidth = Math.max(1, config.graticuleWidth * texelsPerDegree * 0.499999);
    ctx.beginPath();
    for (let lng = -180; lng <= 180; lng += config.graticuleStep) {
      const x = (lng + 180) * texelsPerDegree;
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
    }
    for (let lat = -90 + config.graticuleStep; lat < 90; lat += config.graticuleStep) {
      const y = ((90 - lat) / 180) * height;
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
    }
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  if (config.showOutline) {
    ctx.strokeStyle = config.outlineColor;
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.lineWidth = Math.max(1, config.outlineWidth * texelsPerDegree * 0.5);
    ctx.beginPath();
    for (const offset of [-width, 0, width]) {
      traceRings(ctx, rings, width, height, offset, false);
    }
    ctx.stroke();
  }
}

function buildDottedGlobe(container, initial) {
  // Unwrapped once and reused: the mask and the surface texture both walk it,
  // and the texture is repainted on every colour edit.
  const rings = unwrapRings(decodeLandRings());
  const reduceMotion =
    typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

  let config = { ...initial };
  let disposed = false;
  const software = isSoftwareGL();

  const renderer = new THREE.WebGLRenderer({ antialias: !software, alpha: true });
  renderer.setPixelRatio(software ? 1 : Math.min(globalThis.devicePixelRatio || 1, 2));
  renderer.domElement.style.display = 'block';
  renderer.domElement.style.touchAction = 'none';
  container.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  // Framing is fixed by the pair, not by either number alone: a unit sphere seen
  // from 3.3555 radii under a 50 degree vertical fov subtends
  // tan(asin(1/3.3555)) / tan(25 deg) = 0.6697 of the stage height, and the
  // perspective foreshortening at the limb follows from the same distance. A
  // longer lens further out would reproduce the silhouette and flatten the globe.
  const camera = new THREE.PerspectiveCamera(50, 1, 0.100001, 100);
  camera.position.set(0, 0, 3.35549);

  // Two nested groups so the spin (yaw) and the framing tilt (pitch) never fight
  // over the same Euler angles: the outer one holds the tilt the drag sets, the
  // inner one accumulates rotation forever.
  const tiltGroup = new THREE.Group();
  const spinGroup = new THREE.Group();
  tiltGroup.add(spinGroup);
  scene.add(tiltGroup);

  const surfaceCanvas = document.createElement('canvas');
  surfaceCanvas.width = 2048;
  surfaceCanvas.height = 1024;
  const surfaceTexture = new THREE.CanvasTexture(surfaceCanvas);
  surfaceTexture.colorSpace = THREE.SRGBColorSpace;
  surfaceTexture.anisotropy = software ? 1 : renderer.capabilities.getMaxAnisotropy();
  surfaceTexture.wrapS = THREE.RepeatWrapping;

  const oceanGeometry = new THREE.SphereGeometry(OCEAN_RADIUS, 96, 64);
  const oceanMaterial = new THREE.MeshBasicMaterial({ map: surfaceTexture, transparent: true });
  const ocean = new THREE.Mesh(oceanGeometry, oceanMaterial);
  // Occlusion of the far side is depth, not paint: this sphere writes depth
  // across its silhouette and the dots behind it fail the test. With an opaque
  // fill the draw order happened to come out right; every mesh here is in the
  // same transparent bucket and they all sort on the same origin, so the order
  // was only ever whatever the sort was stable about. Pinning it costs a line.
  ocean.renderOrder = -1;
  spinGroup.add(ocean);

  // A dot is a low-poly sphere rather than the flat disc this started as. A disc
  // has to be turned to face somewhere, and facing it along the surface normal —
  // the only orientation available to a static instance matrix — makes it edge-on
  // exactly at the limb, where the dots are densest: measured against the
  // reference, the outer tenth of the disc kept 36 % of the ink it should have.
  // A sphere has no orientation to get wrong. Six by four segments is where the
  // silhouette stops changing size as the globe turns, and at 36 triangles a
  // 15 000-dot field is still a single instanced draw call.
  const dotGeometry = new THREE.SphereGeometry(1, 6, 4);
  const dotMaterial = new THREE.MeshBasicMaterial({ transparent: true });
  let dots = null;

  const markerGeometry = new THREE.CircleGeometry(1, 20);
  const markerMaterial = new THREE.MeshBasicMaterial({ side: THREE.DoubleSide, transparent: true });
  let markers = null;

  // ---- MandiWay: trade arcs between mandi cities ----------------------------
  const arcGroup = new THREE.Group();
  spinGroup.add(arcGroup);
  const arcs = [];
  const arcMaterialBase = { transparent: true, depthWrite: false };
  function addArc(a, b, color, delay) {
    const v1 = toVector(a[0], a[1], 1.004, new THREE.Vector3());
    const v2 = toVector(b[0], b[1], 1.004, new THREE.Vector3());
    const dist = v1.distanceTo(v2);
    const mid = v1.clone().add(v2).normalize().multiplyScalar(1.004 + dist * 0.6);
    const curve = new THREE.QuadraticBezierCurve3(v1, mid, v2);
    const geo = new THREE.TubeGeometry(curve, 64, 0.0042, 6, false);
    const mat = new THREE.MeshBasicMaterial({ color, ...arcMaterialBase, opacity: 0.95 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.geometry.setDrawRange(0, 0);
    arcGroup.add(mesh);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.008, 12, 8), new THREE.MeshBasicMaterial({ color: 0xffffff, ...arcMaterialBase }));
    arcGroup.add(head);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.01, 0.016, 24), new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, ...arcMaterialBase }));
    ring.position.copy(v2);
    ring.lookAt(v2.clone().multiplyScalar(2));
    arcGroup.add(ring);
    arcs.push({ curve, mesh, mat, head, ring, delay, total: geo.index.count });
  }
  const CITY = config.cities || [];
  const ROUTES = config.routes || [];
  ROUTES.forEach((r, i) => addArc(CITY[r[0]], CITY[r[1]], i % 3 === 2 ? 0x2fd15a : 0xff7a1a, i * 0.55));
  const ARC_CYCLE = 4.2;
  function tickArcs(t) {
    for (const a of arcs) {
      const local = ((t - a.delay) % ARC_CYCLE + ARC_CYCLE) % ARC_CYCLE;
      const grow = Math.min(1, local / 1.4);
      const fade = local < 2.4 ? 1 : Math.max(0, 1 - (local - 2.4) / 1.2);
      const segs = Math.floor(grow * 64);
      a.mesh.geometry.setDrawRange(0, segs * 6 * 6);
      a.mat.opacity = 0.95 * fade;
      const p = a.curve.getPoint(Math.min(grow, 0.999));
      a.head.position.copy(p);
      a.head.material.opacity = grow < 1 ? 1 : 0;
      const pulse = grow >= 1 ? Math.min(1, (local - 1.4) / 0.8) : 0;
      a.ring.scale.setScalar(1 + pulse * 3);
      a.ring.material.opacity = grow >= 1 ? (1 - pulse) * fade : 0;
    }
  }
  function showArcsStatic() {
    for (const a of arcs) { a.mesh.geometry.setDrawRange(0, a.total); a.mat.opacity = 0.8; a.head.material.opacity = 0; a.ring.material.opacity = 0; }
  }
  let swayBase = null;
  let zoom = 1;

  let land = null;
  let landSpacing = null;
  let landOnly = null;

  const scratchVector = new THREE.Vector3();
  const scratchMatrix = new THREE.Matrix4();
  const scratchQuaternion = new THREE.Quaternion();
  const scratchScale = new THREE.Vector3();
  const scratchNormal = new THREE.Vector3();
  const outward = new THREE.Vector3(0, 0, 1);

  // A dot is a flat disc pushed out to the surface and turned to face away from
  // the centre, which is what keeps it a dot at the limb instead of an edge-on
  // sliver.
  function placeInstances(mesh, coords, radius, scale) {
    for (let i = 0; i < coords.length / 2; i += 1) {
      toVector(coords[i * 2], coords[i * 2 + 1], radius, scratchVector);
      scratchNormal.copy(scratchVector).normalize();
      scratchQuaternion.setFromUnitVectors(outward, scratchNormal);
      scratchScale.setScalar(scale);
      scratchMatrix.compose(scratchVector, scratchQuaternion, scratchScale);
      mesh.setMatrixAt(i, scratchMatrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
    mesh.computeBoundingSphere();
  }

  function rebuildDots() {
    if (dots) {
      spinGroup.remove(dots);
      dots.dispose();
      dots = null;
    }
    if (config.fill !== 'dots') return;

    const coords = dotPositions(land, config.dotSpacing, config.landOnly);
    if (!coords.length) return;
    dots = new THREE.InstancedMesh(dotGeometry, dotMaterial, coords.length / 2);
    dots.frustumCulled = false;
    // A dot's radius is a fraction of the spacing, so raising density thins the
    // dots instead of merging the field into a solid shell.
    const scale = (config.dotSpacing * DEG * config.dotSize) / 2;
    placeInstances(dots, coords, DOT_RADIUS, scale);
    spinGroup.add(dots);
  }

  function rebuildMarkers() {
    if (markers) {
      spinGroup.remove(markers);
      markers.dispose();
      markers = null;
    }
    const parsed = parseMarkers(config.markers);
    if (!parsed.length) return;
    const coords = parsed.flatMap((marker) => [marker.lat, marker.lng]);
    markers = new THREE.InstancedMesh(markerGeometry, markerMaterial, parsed.length);
    markers.frustumCulled = false;
    placeInstances(markers, coords, MARKER_RADIUS, config.markerSize * DEG);
    spinGroup.add(markers);
  }

  function repaintSurface() {
    paintSurface(surfaceCanvas, rings, config);
    surfaceTexture.needsUpdate = true;
  }

  function applyColors() {
    dotMaterial.color.set(config.dotColor);
    dotMaterial.opacity = config.dotOpacity;
    markerMaterial.color.set(config.markerColor);
  }

  // Only the dot field depends on the mask, and only its resolution depends on
  // the spacing, so a colour edit never pays for a rasterisation.
  function ensureLand() {
    const wantsMask = config.fill === 'dots' && config.landOnly;
    const width = config.dotSpacing < 1 && !software ? 4096 : 2048;
    if (!wantsMask) {
      if (!land) land = { mask: new Uint8Array(1).fill(1), width: 1, height: 1 };
      return;
    }
    if (land && land.width === width) return;
    land = buildLandMask(rings, width, width / 2);
  }

  function resizeSurface() {
    const wide = Math.max(container.clientWidth, container.clientHeight) >= 560 && !software;
    const width = wide ? 4096 : 2048;
    if (surfaceCanvas.width === width) return false;
    surfaceCanvas.width = width;
    surfaceCanvas.height = width / 2;
    return true;
  }

  function rebuild(previous) {
    ensureLand();
    const spacingChanged =
      landSpacing !== config.dotSpacing || landOnly !== config.landOnly || previous?.fill !== config.fill;
    landSpacing = config.dotSpacing;
    landOnly = config.landOnly;

    if (spacingChanged || previous?.dotSize !== config.dotSize) rebuildDots();
    rebuildMarkers();
    applyColors();
    repaintSurface();
    tiltGroup.rotation.x = config.tilt * DEG;
    spinGroup.scale.setScalar(config.scale);
    dirty = true;
  }

  // ---- interaction -------------------------------------------------------
  let yaw = 0;
  let pitch = 0;
  let velocityYaw = 0;
  let velocityPitch = 0;
  let dragging = false;
  let hovering = false;
  let pointerId = null;
  let lastX = 0;
  let lastY = 0;

  const element = renderer.domElement;

  function onPointerDown(event) {
    if (pointerId !== null) return;
    pointerId = event.pointerId;
    dragging = true;
    lastX = event.clientX;
    lastY = event.clientY;
    element.setPointerCapture(pointerId);
  }

  function onPointerMove(event) {
    if (!dragging || event.pointerId !== pointerId) return;
    const dx = event.clientX - lastX;
    const dy = event.clientY - lastY;
    lastX = event.clientX;
    lastY = event.clientY;
    const sensitivity = config.dragSensitivity * 0.00499999;
    velocityYaw = dx * sensitivity;
    velocityPitch = dy * sensitivity;
    yaw += velocityYaw;
    pitch += velocityPitch;
  }

  function endDrag(event) {
    if (event.pointerId !== pointerId) return;
    dragging = false;
    if (element.hasPointerCapture(pointerId)) element.releasePointerCapture(pointerId);
    pointerId = null;
  }

  const onEnter = () => {
    hovering = true;
  };
  const onLeave = () => {
    hovering = false;
  };

  element.addEventListener('pointerdown', onPointerDown);
  element.addEventListener('pointermove', onPointerMove);
  element.addEventListener('pointerup', endDrag);
  element.addEventListener('pointercancel', endDrag);
  element.addEventListener('pointerenter', onEnter);
  element.addEventListener('pointerleave', onLeave);

  // ---- loop --------------------------------------------------------------
  let frame = 0;
  let previousTime = 0;
  // Set by anything that changes the picture without moving it (a rebuild, a
  // resize): the loop only draws when the globe turns or the picture changed,
  // so a still globe costs nothing per frame, and a software rasteriser is not
  // asked to redraw the same frame 60 times a second.
  let dirty = true;
  let lastDraw = -Infinity;
  const SOFTWARE_FRAME_MS = 100;

  function render(time) {
    if (disposed) return;
    frame = requestAnimationFrame(render);
    // A software rasteriser gets ten frames a second at most. The clock is read
    // only on frames that go on to draw, so the spin covers the skipped ones;
    // the clamp that stops a tab-away turning into a jump widens to match.
    if (software && time - lastDraw < SOFTWARE_FRAME_MS && !dirty) return;
    const delta = previousTime ? Math.min((time - previousTime) / 1000, software ? 0.149999 : 0.0500001) : 0;
    previousTime = time;

    if (!dragging) {
      // One exponential decay for the throw, and the same clock drives the idle
      // spin, so releasing a drag blends into auto-rotation rather than snapping.
      const damping = Math.exp(-config.friction * delta * 10);
      velocityYaw *= damping;
      velocityPitch *= damping;
      yaw += velocityYaw;
      pitch += velocityPitch;

      const idle = reduceMotion || (config.stopOnHover && hovering) ? 0 : config.spin;
      yaw += config.direction * idle * DEG * delta;
      if (idle !== 0 || Math.abs(velocityYaw) > 1e-6 || Math.abs(velocityPitch) > 1e-6) dirty = true;
    } else {
      dirty = true;
    }
    if (!reduceMotion && arcs.length) { tickArcs(time / 1000); dirty = true; }
    if (!dirty) return;

    // The pole is a singularity for this control scheme: past it the drag axis
    // inverts and the globe feels broken, so the tilt is clamped short of it.
    const limit = 75 * DEG;
    pitch = Math.min(limit, Math.max(-limit, pitch));

    const sway = !reduceMotion && config.sway && !dragging ? Math.sin(time / 1000 * 0.35) * config.sway * DEG : 0;
    spinGroup.rotation.y = yaw + sway;
    camera.position.z = 3.35549 / zoom;
    tiltGroup.rotation.x = config.tilt * DEG + pitch;

    renderer.render(scene, camera);
    dirty = false;
    lastDraw = time;
  }

  // ---- sizing ------------------------------------------------------------
  function resize() {
    const width = Math.max(container.clientWidth, 1);
    const height = Math.max(container.clientHeight, 1);
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    if (resizeSurface()) repaintSurface();
    dirty = true;
  }

  const observer = new ResizeObserver(resize);
  observer.observe(container);

  yaw = -(config.longitude ?? 0) * DEG;
  resizeSurface();
  rebuild(null);
  resize();
  frame = requestAnimationFrame(render);

  if (reduceMotion) showArcsStatic();
  return {
    setZoom(z) { zoom = z; dirty = true; },
    pause() { if (frame) { cancelAnimationFrame(frame); frame = 0; } },
    resume() { if (!frame && !disposed) { previousTime = 0; dirty = true; frame = requestAnimationFrame(render); } },
    update(next) {
      const previous = config;
      config = { ...next };
      if (previous.longitude !== config.longitude) yaw = -config.longitude * DEG;
      rebuild(previous);
    },
    destroy() {
      disposed = true;
      cancelAnimationFrame(frame);
      observer.disconnect();
      element.removeEventListener('pointerdown', onPointerDown);
      element.removeEventListener('pointermove', onPointerMove);
      element.removeEventListener('pointerup', endDrag);
      element.removeEventListener('pointercancel', endDrag);
      element.removeEventListener('pointerenter', onEnter);
      element.removeEventListener('pointerleave', onLeave);
      dots?.dispose();
      markers?.dispose();
      dotGeometry.dispose();
      markerGeometry.dispose();
      oceanGeometry.dispose();
      dotMaterial.dispose();
      markerMaterial.dispose();
      oceanMaterial.dispose();
      surfaceTexture.dispose();
      renderer.dispose();
      // Give the context back now rather than when the garbage collector gets
      // to it: a catalogue page mounts several of these, and a browser holds
      // only so many WebGL contexts before it starts losing the oldest.
      renderer.forceContextLoss();
      element.remove();
    }
  };
}


export { buildDottedGlobe };
